mapper.select:
SELECT DICT_TYPE AS dictType, FIELD_TYPE AS fieldType, FIELD_NAME AS fieldName, parentId, REMARKS, TENANT_ID, SELECT_ABLE, SORT FROM SYS_DICT_INFO WHERE ENABLE_STATE = 1 AND ( TENANT_ID IS NULL
OR TENANT_ID = #{tenantId}
)
AND DICT_TYPE LIKE #{type}
GROUP BY DICT_TYPE,FIELD_TYPE,FIELD_NAME,parentId,TENANT_ID,REMARKS,SELECT_ABLE,SORT ORDER BY SORT ASC

SELECT DI.ID, DI.DICT_TYPE , DI.FIELD_TYPE , DI.FIELD_NAME , DI.SORT, DI.REMARKS, DI.TENANT_ID, DI.FOUND_TIME , DI.FOUND_PEOPLE , DI.UPDATE_TIME , DI.UPDATE_PEOPLE , DI.ENABLE_STATE , DT.DICT_NAME, DI.PARENTID, DI.PARENTKEYS , DI.EXTRA, DI.SELECT_ABLE FROM SYS_DICT_INFO DI INNER JOIN SYS_DICT_TYPE DT ON DT.DICT_TYPE = DI.DICT_TYPE
( DI.TENANT_ID IS NULL
OR DI.TENANT_ID = #{parameters.tenantId}
)
AND DI.DICT_TYPE = #{parameters.dictType}
AND DI.FIELD_TYPE LIKE #{parameters.fieldType}
AND DI.FIELD_NAME LIKE #{parameters.fieldName}
AND DI.ENABLE_STATE = #{parameters.enableState}
AND DI.PARENTID = #{parameters.dictInfoId}
ORDER BY DI.DICT_TYPE, DI.SORT ASC, DI.ID DESC

SELECT DI.ID, DI.DICT_TYPE , DI.FIELD_TYPE , DI.FIELD_NAME , DI.SORT, DI.REMARKS, DI.TENANT_ID, DI.FOUND_TIME , DI.FOUND_PEOPLE , DI.UPDATE_TIME , DI.UPDATE_PEOPLE , DI.ENABLE_STATE , DT.DICT_NAME, DI.EXTRA, DI.SELECT_ABLE FROM SYS_DICT_INFO DI INNER JOIN SYS_DICT_TYPE DT ON DT.DICT_TYPE = DI.DICT_TYPE WHERE DI.DICT_TYPE = #{dictInfo.dictType} AND ( DI.TENANT_ID IS NULL
OR DI.TENANT_ID = #{dictInfo.tenantId}
)
AND DI.ID = #{dictInfo.id}
OR DI.PARENTKEYS LIKE #{dictInfo.parentId}
AND DI.RANK2 <= #{dictInfo.rank}

SELECT DI.ID, DI.DICT_TYPE , DI.FIELD_TYPE , DI.FIELD_NAME , DI.SORT, DI.REMARKS, DI.TENANT_ID, DI.FOUND_TIME , DI.FOUND_PEOPLE , DI.UPDATE_TIME , DI.UPDATE_PEOPLE , DI.ENABLE_STATE , DI.PARENTID , DI.PARENTKEYS , DI.EXTRA, DI.SELECT_ABLE FROM SYS_DICT_INFO DI INNER JOIN SYS_DICT_TYPE DT ON DT.DICT_TYPE = DI.DICT_TYPE WHERE DI.ENABLE_STATE = 1 AND ( DI.TENANT_ID IS NULL
OR DI.TENANT_ID = #{tenantId}
) AND DT.ID IN
#{item}

SELECT DI.*
FROM SYS_DICT_INFO DI
INNER JOIN SYS_DICT_TYPE DT ON DT.DICT_TYPE = DI.DICT_TYPE

    (
    DI.TENANT_ID IS NULL

        OR DI.TENANT_ID = #{parameters.tenantId}

    )

        AND DI.DICT_TYPE = #{parameters.dictType}


        AND DI.FIELD_TYPE LIKE  #{parameters.fieldType}


        AND DI.FIELD_NAME LIKE  #{parameters.fieldName}


        AND DI.ENABLE_STATE = #{parameters.enableState}


        AND DI.PARENTID = #{parameters.dictInfoId}


ORDER BY DI.DICT_TYPE, DI.SORT ASC, DI.ID DESC
